// axi_driver.sv
// Converts sequence items into pin-level AXI stimulus via the virtual interface

class axi_driver extends uvm_driver #(axi_seq_item);
  `uvm_component_utils(axi_driver)

  virtual axi_if vif;

  function new(string name = "axi_driver", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db#(virtual axi_if)::get(this, "", "vif", vif))
      `uvm_fatal("NOVIF", "Virtual interface not found for axi_driver")
  endfunction

  task run_phase(uvm_phase phase);
    // Initialize all master-driven signals
    init_signals();

    forever begin
      axi_seq_item item;
      seq_item_port.get_next_item(item);

      if (item.txn_type == axi_seq_item::WRITE)
        drive_write(item);
      else
        drive_read(item);

      seq_item_port.item_done();
    end
  endtask

  // Initialize all master outputs to idle
  task init_signals();
    @(vif.drv_cb);
    vif.drv_cb.AWVALID <= 0;
    vif.drv_cb.AWID    <= 0;
    vif.drv_cb.AWADDR  <= 0;
    vif.drv_cb.AWLEN   <= 0;
    vif.drv_cb.AWSIZE  <= 0;
    vif.drv_cb.AWBURST <= 0;
    vif.drv_cb.WVALID  <= 0;
    vif.drv_cb.WDATA   <= 0;
    vif.drv_cb.WSTRB   <= 0;
    vif.drv_cb.WLAST   <= 0;
    vif.drv_cb.BREADY  <= 0;
    vif.drv_cb.ARVALID <= 0;
    vif.drv_cb.ARID    <= 0;
    vif.drv_cb.ARADDR  <= 0;
    vif.drv_cb.ARLEN   <= 0;
    vif.drv_cb.ARSIZE  <= 0;
    vif.drv_cb.ARBURST <= 0;
    vif.drv_cb.RREADY  <= 0;
  endtask

  // Drive a complete write transaction: AW handshake → W beats → B handshake
  // Drive a complete write transaction: AW handshake → W beats → B handshake
  task drive_write(axi_seq_item item);
    // AW channel
    @(vif.drv_cb);
    vif.drv_cb.AWID    <= item.id;
    vif.drv_cb.AWADDR  <= item.addr;
    vif.drv_cb.AWLEN   <= item.len;
    vif.drv_cb.AWSIZE  <= item.size;
    vif.drv_cb.AWBURST <= item.burst;
    vif.drv_cb.AWVALID <= 1;

    // Wait for AW handshake
    do @(vif.drv_cb);
    while (!vif.drv_cb.AWREADY);

    vif.drv_cb.AWVALID <= 0;

    // W channel: drive each beat
    for (int beat = 0; beat <= item.len; beat++) begin
      // (The extra @(vif.drv_cb) was removed here for the timing fix)
      vif.drv_cb.WDATA  <= item.wdata[beat];
      vif.drv_cb.WSTRB  <= item.wstrb[beat];
      vif.drv_cb.WLAST  <= (beat == item.len);
      vif.drv_cb.WVALID <= 1;

      // Wait for W handshake
      do @(vif.drv_cb);
      while (!vif.drv_cb.WREADY);
    end

    vif.drv_cb.WVALID <= 0;
    vif.drv_cb.WLAST  <= 0;
    
    // B channel: wait for BVALID, apply optional delay, then assert BREADY
    // Wait for BVALID
    while (!vif.drv_cb.BVALID)
      @(vif.drv_cb);

    // Apply BREADY delay
    repeat (item.bready_delay) @(vif.drv_cb);

    vif.drv_cb.BREADY <= 1;
    @(vif.drv_cb);
    vif.drv_cb.BREADY <= 0;
  endtask

  // Drive a complete read transaction: AR handshake → R beats
  task drive_read(axi_seq_item item);
    // AR channel
    @(vif.drv_cb);
    vif.drv_cb.ARID    <= item.id;
    vif.drv_cb.ARADDR  <= item.addr;
    vif.drv_cb.ARLEN   <= item.len;
    vif.drv_cb.ARSIZE  <= item.size;
    vif.drv_cb.ARBURST <= item.burst;
    vif.drv_cb.ARVALID <= 1;

    // Wait for AR handshake
    do @(vif.drv_cb);
    while (!vif.drv_cb.ARREADY);

    vif.drv_cb.ARVALID <= 0;

    // R channel: accept each beat
    for (int beat = 0; beat <= item.len; beat++) begin
      // Wait for RVALID
      while (!vif.drv_cb.RVALID)
        @(vif.drv_cb);

      // Apply RREADY delay
      repeat (item.rready_delay) @(vif.drv_cb);

      vif.drv_cb.RREADY <= 1;
      @(vif.drv_cb);
      vif.drv_cb.RREADY <= 0;
    end
  endtask

endclass

