// axi_monitor.sv
// Samples DUT interface signals and broadcasts transactions via analysis ports

class axi_monitor extends uvm_monitor;
  `uvm_component_utils(axi_monitor)

  virtual axi_if vif;

  // Separate analysis ports for write and read transactions
  uvm_analysis_port #(axi_seq_item) wr_ap;
  uvm_analysis_port #(axi_seq_item) rd_ap;

  function new(string name = "axi_monitor", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db#(virtual axi_if)::get(this, "", "vif", vif))
      `uvm_fatal("NOVIF", "Virtual interface not found for axi_monitor")
    wr_ap = new("wr_ap", this);
    rd_ap = new("rd_ap", this);
  endfunction

  task run_phase(uvm_phase phase);
    // Wait for reset de-assertion
    wait(vif.ARESETn === 1'b1);
    @(vif.mon_cb);

    fork
      monitor_write();
      monitor_read();
    join_none
  endtask

  // Monitor write transactions: AW → W beats → B response
  task monitor_write();
    forever begin
      axi_seq_item item;
      item = axi_seq_item::type_id::create("wr_mon_item");
      item.txn_type = axi_seq_item::WRITE;

      // Wait for AW handshake
      while (!(vif.mon_cb.AWVALID && vif.mon_cb.AWREADY))
        @(vif.mon_cb);

      item.id    = vif.mon_cb.AWID;
      item.addr  = vif.mon_cb.AWADDR;
      item.len   = vif.mon_cb.AWLEN;
      item.size  = vif.mon_cb.AWSIZE;
      item.burst = vif.mon_cb.AWBURST;

      // Collect W beats
      item.wdata = new[item.len + 1];
      item.wstrb = new[item.len + 1];

      for (int beat = 0; beat <= item.len; beat++) begin
        @(vif.mon_cb);
        while (!(vif.mon_cb.WVALID && vif.mon_cb.WREADY))
          @(vif.mon_cb);

        item.wdata[beat] = vif.mon_cb.WDATA;
        item.wstrb[beat] = vif.mon_cb.WSTRB;
      end

      // Wait for B handshake
      @(vif.mon_cb);
      while (!(vif.mon_cb.BVALID && vif.mon_cb.BREADY))
        @(vif.mon_cb);

      item.resp_id = vif.mon_cb.BID;
      item.resp    = vif.mon_cb.BRESP;

      `uvm_info(get_type_name(), $sformatf("WR TXN: addr=%08h id=%0h len=%0d resp=%0b",
                item.addr, item.id, item.len, item.resp), UVM_HIGH)

      wr_ap.write(item);
    end
  endtask

  // Monitor read transactions: AR → R beats
  task monitor_read();
    forever begin
      axi_seq_item item;
      item = axi_seq_item::type_id::create("rd_mon_item");
      item.txn_type = axi_seq_item::READ;

      // Wait for AR handshake
      while (!(vif.mon_cb.ARVALID && vif.mon_cb.ARREADY))
        @(vif.mon_cb);

      item.id    = vif.mon_cb.ARID;
      item.addr  = vif.mon_cb.ARADDR;
      item.len   = vif.mon_cb.ARLEN;
      item.size  = vif.mon_cb.ARSIZE;
      item.burst = vif.mon_cb.ARBURST;

      // Collect R beats
      item.rdata  = new[item.len + 1];
      item.rlast  = new[item.len + 1];
      item.rresp  = new[item.len + 1];

      for (int beat = 0; beat <= item.len; beat++) begin
        @(vif.mon_cb);
        while (!(vif.mon_cb.RVALID && vif.mon_cb.RREADY))
          @(vif.mon_cb);

        item.rdata[beat]  = vif.mon_cb.RDATA;
        item.rlast[beat]  = vif.mon_cb.RLAST;
        item.rresp[beat]  = vif.mon_cb.RRESP;
        item.resp_id      = vif.mon_cb.RID;
      end

      item.resp = item.rresp[0];  // store first beat response

      `uvm_info(get_type_name(), $sformatf("RD TXN: addr=%08h id=%0h len=%0d resp=%0b",
                item.addr, item.id, item.len, item.resp), UVM_HIGH)

      rd_ap.write(item);
    end
  endtask

endclass

// ════════════════════════════════════════════════════════════
// Scoreboard (uvm_scoreboard)
// ════════════════════════════════════════════════════════════

// axi_scoreboard.sv
// Reference model + checker for AXI memory slave
// Analysis export specializations for scoreboard
`uvm_analysis_imp_decl(_wr)
`uvm_analysis_imp_decl(_rd)

class axi_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(axi_scoreboard)

  // Analysis exports to receive transactions from the monitor
  uvm_analysis_imp_wr #(axi_seq_item, axi_scoreboard) wr_imp;
  uvm_analysis_imp_rd #(axi_seq_item, axi_scoreboard) rd_imp;

  // Reference memory model
  bit [31:0] ref_mem [int unsigned];

  // Counters
  int wr_count, rd_count, pass_count, fail_count;

  // Parameters matching DUT
  localparam int MEM_DEPTH  = 256;
  localparam int DATA_BYTES = 4;
  localparam int ADDR_LSB   = 2;
  localparam int MAX_SIZE_ENC = 2;

  function new(string name = "axi_scoreboard", uvm_component parent = null);
    super.new(name, parent);
    wr_count = 0;
    rd_count = 0;
    pass_count = 0;
    fail_count = 0;
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    wr_imp = new("wr_imp", this);
    rd_imp = new("rd_imp", this);
  endfunction

  // ------ Helper functions mirroring DUT logic ------

  function bit size_ok(bit [2:0] axsize);
    return (axsize <= MAX_SIZE_ENC);
  endfunction

  function bit burst_ok(bit [1:0] axburst);
    return (axburst != 2'b11);
  endfunction

  function bit wrap_len_ok(bit [7:0] axlen);
    int unsigned beats;
    beats = axlen + 1;
    return (beats == 2) || (beats == 4) || (beats == 8) || (beats == 16);
  endfunction

  function bit addr_aligned_to_size(bit [31:0] addr, bit [2:0] axsize);
    bit [31:0] mask;
    mask = (1 << axsize) - 1;
    return ((addr & mask) == 0);
  endfunction

  function bit req_ok(bit [31:0] addr, bit [2:0] axsize, bit [7:0] axlen, bit [1:0] axburst);
    bit sz_ok, br_ok, wr_ok;
    sz_ok = size_ok(axsize);
    br_ok = burst_ok(axburst);
    if (axburst == 2'b10) // WRAP
      wr_ok = sz_ok && addr_aligned_to_size(addr, axsize) && wrap_len_ok(axlen);
    else
      wr_ok = 1;
    return sz_ok && br_ok && wr_ok;
  endfunction

  function bit [31:0] next_addr_axi(
    bit [31:0] cur_addr, bit [31:0] start_addr,
    bit [2:0] axsize, bit [1:0] axburst,
    bit [7:0] axlen, bit [7:0] beat_idx
  );
    bit [31:0] size_bytes, size_mask, aligned_addr;
    bit [31:0] container_bytes, wrap_boundary, upper_wrap_boundary, nxt;

    size_bytes       = (1 << axsize);
    size_mask        = size_bytes - 1;
    aligned_addr     = start_addr & ~size_mask;
    container_bytes  = size_bytes * (axlen + 1);
    wrap_boundary    = start_addr - (start_addr % container_bytes);
    upper_wrap_boundary = wrap_boundary + container_bytes;

    case (axburst)
      2'b00: nxt = cur_addr;  // FIXED
      2'b10: begin  // WRAP
        if ((beat_idx == 0) && ((start_addr & size_mask) != 0))
          nxt = aligned_addr + size_bytes;
        else
          nxt = cur_addr + size_bytes;
        if (nxt >= upper_wrap_boundary)
          nxt = wrap_boundary;
      end
      default: begin  // INCR
        if ((beat_idx == 0) && ((start_addr & size_mask) != 0))
          nxt = aligned_addr + size_bytes;
        else
          nxt = cur_addr + size_bytes;
      end
    endcase
    return nxt;
  endfunction

  // ------ Write transaction handler ------
  function void write_wr(axi_seq_item item);
    bit error;
    bit [31:0] addr;
    int unsigned widx;

    wr_count++;
    error = !req_ok(item.addr, item.size, item.len, item.burst);

    // Check BID matches AWID
    if (item.resp_id !== item.id)
      `uvm_error("SCB", $sformatf("BID mismatch: expected %0h, got %0h", item.id, item.resp_id))

    addr = item.addr;

    for (int beat = 0; beat <= item.len; beat++) begin
      if (!error) begin
        widx = addr >> ADDR_LSB;
        if (widx < MEM_DEPTH) begin
          // Update reference memory with byte strobes
          if (!ref_mem.exists(widx))
            ref_mem[widx] = 0;
          for (int b = 0; b < DATA_BYTES; b++) begin
            if (item.wstrb[beat][b])
              ref_mem[widx][b*8 +: 8] = item.wdata[beat][b*8 +: 8];
          end
        end else begin
          error = 1;
        end
      end

      if (beat < item.len)
        addr = next_addr_axi(addr, item.addr, item.size, item.burst, item.len, beat);
    end

    // Check BRESP
    if (error) begin
      if (item.resp !== 2'b10)
        `uvm_error("SCB", $sformatf("Expected SLVERR for write, got BRESP=%0b addr=%08h", item.resp, item.addr))
      else
        pass_count++;
    end else begin
      if (item.resp !== 2'b00)
        `uvm_error("SCB", $sformatf("Expected OKAY for write, got BRESP=%0b addr=%08h", item.resp, item.addr))
      else
        pass_count++;
    end

    `uvm_info("SCB", $sformatf("WR #%0d: addr=%08h len=%0d burst=%0d resp=%0b %s",
              wr_count, item.addr, item.len, item.burst, item.resp,
              error ? "ERROR" : "OK"), UVM_MEDIUM)
  endfunction

  // ------ Read transaction handler ------
  function void write_rd(axi_seq_item item);
    bit error;
    bit [31:0] addr;
    bit [31:0] expected_data;
    int unsigned widx;

    rd_count++;
    error = !req_ok(item.addr, item.size, item.len, item.burst);

    // Check RID matches ARID
    if (item.resp_id !== item.id)
      `uvm_error("SCB", $sformatf("RID mismatch: expected %0h, got %0h", item.id, item.resp_id))

    addr = item.addr;

    for (int beat = 0; beat <= item.len; beat++) begin
      // Check RLAST
      if (beat == item.len) begin
        if (!item.rlast[beat])
          `uvm_error("SCB", $sformatf("RLAST not set on final beat %0d", beat))
      end else begin
        if (item.rlast[beat])
          `uvm_error("SCB", $sformatf("RLAST set prematurely on beat %0d", beat))
      end

      // Check RRESP
      if (error) begin
        if (item.rresp[beat] !== 2'b10)
          `uvm_error("SCB", $sformatf("Expected SLVERR on read beat %0d, got %0b", beat, item.rresp[beat]))
      end else begin
        if (item.rresp[beat] !== 2'b00)
          `uvm_error("SCB", $sformatf("Expected OKAY on read beat %0d, got %0b", beat, item.rresp[beat]))
      end

      // Check RDATA for non-error reads with full-width aligned transfers
      if (!error && item.size == 2) begin  // full word
        widx = addr >> ADDR_LSB;
        if (widx < MEM_DEPTH) begin
          expected_data = ref_mem.exists(widx) ? ref_mem[widx] : 32'h0;
          if (item.rdata[beat] !== expected_data) begin
            `uvm_error("SCB", $sformatf("RDATA mismatch beat %0d addr=%08h: exp=%08h got=%08h",
                       beat, addr, expected_data, item.rdata[beat]))
            fail_count++;
          end else begin
            pass_count++;
          end
        end
      end else if (!error) begin
        pass_count++;  // narrow transfers — harder to check, trust SVA
      end

      if (beat < item.len)
        addr = next_addr_axi(addr, item.addr, item.size, item.burst, item.len, beat);
    end

    `uvm_info("SCB", $sformatf("RD #%0d: addr=%08h len=%0d burst=%0d resp=%0b %s",
              rd_count, item.addr, item.len, item.burst, item.resp,
              error ? "ERROR" : "OK"), UVM_MEDIUM)
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("SCB", $sformatf("=== SCOREBOARD SUMMARY ==="), UVM_LOW)
    `uvm_info("SCB", $sformatf("  Write transactions: %0d", wr_count), UVM_LOW)
    `uvm_info("SCB", $sformatf("  Read transactions:  %0d", rd_count), UVM_LOW)
    `uvm_info("SCB", $sformatf("  Pass checks:        %0d", pass_count), UVM_LOW)
    `uvm_info("SCB", $sformatf("  Fail checks:        %0d", fail_count), UVM_LOW)
    if (fail_count > 0)
      `uvm_error("SCB", "*** TEST FAILED — mismatches detected ***")
    else
      `uvm_info("SCB", "*** ALL CHECKS PASSED ***", UVM_LOW)
  endfunction

endclass

// ════════════════════════════════════════════════════════════
// Functional Coverage (uvm_subscriber)
// ════════════════════════════════════════════════════════════

// axi_coverage.sv
// Functional coverage subscriber for AXI transactions

class axi_coverage extends uvm_subscriber #(axi_seq_item);
  `uvm_component_utils(axi_coverage)

  axi_seq_item item;

  // Covergroup for write transactions
  covergroup cg_write with function sample(axi_seq_item t);
    cp_burst: coverpoint t.burst {
      bins fixed = {2'b00};
      bins incr  = {2'b01};
      bins wrap  = {2'b10};
      bins rsvd  = {2'b11};
    }

    cp_size: coverpoint t.size {
      bins byte_s  = {0};
      bins hword_s = {1};
      bins word_s  = {2};
      bins illegal = {[3:7]};
    }

    cp_len: coverpoint t.len {
      bins single_b = {0};
      bins short_b  = {[1:3]};
      bins medium_b = {[4:7]};
      bins long_b   = {[8:15]};
    }

    cp_id: coverpoint t.id {
      bins ids[] = {[0:15]};
    }

    cp_resp: coverpoint t.resp {
      bins okay   = {2'b00};
      bins slverr = {2'b10};
    }

    cp_addr_range: coverpoint t.addr[11:2] {
      bins low    = {[0:63]};
      bins mid    = {[64:191]};
      bins high   = {[192:255]};
      bins oor    = {[256:1023]};
    }

    cp_strb: coverpoint t.wstrb[0] {
      bins full    = {4'hF};
      bins partial = {4'h1, 4'h3, 4'h7};
      bins other   = default;
    }

    cx_burst_len: cross cp_burst, cp_len;
    cx_burst_resp: cross cp_burst, cp_resp;
    cx_size_resp: cross cp_size, cp_resp;
  endgroup

  // Covergroup for read transactions
  covergroup cg_read with function sample(axi_seq_item t);
    cp_burst: coverpoint t.burst {
      bins fixed = {2'b00};
      bins incr  = {2'b01};
      bins wrap  = {2'b10};
      bins rsvd  = {2'b11};
    }

    cp_size: coverpoint t.size {
      bins byte_s  = {0};
      bins hword_s = {1};
      bins word_s  = {2};
      bins illegal = {[3:7]};
    }

    cp_len: coverpoint t.len {
      bins single_b = {0};
      bins short_b  = {[1:3]};
      bins medium_b = {[4:7]};
      bins long_b   = {[8:15]};
    }

    cp_id: coverpoint t.id {
      bins ids[] = {[0:15]};
    }

    cp_resp: coverpoint t.resp {
      bins okay   = {2'b00};
      bins slverr = {2'b10};
    }

    cp_addr_range: coverpoint t.addr[11:2] {
      bins low    = {[0:63]};
      bins mid    = {[64:191]};
      bins high   = {[192:255]};
      bins oor    = {[256:1023]};
    }

    cx_burst_len: cross cp_burst, cp_len;
    cx_burst_resp: cross cp_burst, cp_resp;
  endgroup

  // Covergroup for transaction types
  covergroup cg_txn_type with function sample(axi_seq_item t);
    cp_type: coverpoint t.txn_type {
      bins write = {axi_seq_item::WRITE};
      bins read  = {axi_seq_item::READ};
    }
  endgroup

  function new(string name = "axi_coverage", uvm_component parent = null);
    super.new(name, parent);
    cg_write    = new();
    cg_read     = new();
    cg_txn_type = new();
  endfunction

  function void write(axi_seq_item t);
    cg_txn_type.sample(t);
    if (t.txn_type == axi_seq_item::WRITE)
      cg_write.sample(t);
    else
      cg_read.sample(t);
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("COV", $sformatf("Write coverage:    %.1f%%", cg_write.get_coverage()), UVM_LOW)
    `uvm_info("COV", $sformatf("Read coverage:     %.1f%%", cg_read.get_coverage()), UVM_LOW)
    `uvm_info("COV", $sformatf("Txn type coverage: %.1f%%", cg_txn_type.get_coverage()), UVM_LOW)
  endfunction

endclass

// ════════════════════════════════════════════════════════════
// Agent (uvm_agent)
// ════════════════════════════════════════════════════════════

// axi_agent.sv
// AXI agent bundling driver, sequencer, and monitor

class axi_agent extends uvm_agent;
  `uvm_component_utils(axi_agent)

  axi_driver    drv;
  axi_sequencer sqr;
  axi_monitor   mon;

  function new(string name = "axi_agent", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);

    // Monitor is always created
    mon = axi_monitor::type_id::create("mon", this);

    // Driver and sequencer only in ACTIVE mode
    if (get_is_active() == UVM_ACTIVE) begin
      drv = axi_driver::type_id::create("drv", this);
      sqr = axi_sequencer::type_id::create("sqr", this);
    end
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    if (get_is_active() == UVM_ACTIVE)
      drv.seq_item_port.connect(sqr.seq_item_export);
  endfunction

endclass

// ════════════════════════════════════════════════════════════
// Environment (uvm_env)
// ════════════════════════════════════════════════════════════

// axi_env.sv
// UVM environment instantiating agent, scoreboard, and coverage

class axi_env extends uvm_env;
  `uvm_component_utils(axi_env)

  axi_agent      agt;
  axi_scoreboard scb;
  axi_coverage   cov_wr;
  axi_coverage   cov_rd;

  function new(string name = "axi_env", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    agt    = axi_agent::type_id::create("agt", this);
    scb    = axi_scoreboard::type_id::create("scb", this);
    cov_wr = axi_coverage::type_id::create("cov_wr", this);
    cov_rd = axi_coverage::type_id::create("cov_rd", this);
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    // Connect monitor analysis ports to scoreboard and coverage
    agt.mon.wr_ap.connect(scb.wr_imp);
    agt.mon.rd_ap.connect(scb.rd_imp);
    agt.mon.wr_ap.connect(cov_wr.analysis_export);
    agt.mon.rd_ap.connect(cov_rd.analysis_export);
  endfunction

endclass

// ════════════════════════════════════════════════════════════
// Test (uvm_test)
// ════════════════════════════════════════════════════════════

// axi_test.sv
// Top-level UVM test

class axi_base_test extends uvm_test;
  `uvm_component_utils(axi_base_test)

  axi_env env;

  function new(string name = "axi_base_test", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    env = axi_env::type_id::create("env", this);
  endfunction

  task run_phase(uvm_phase phase);
    axi_master_seq master_seq;

    phase.raise_objection(this, "Starting AXI test");

    // Wait for reset to complete
    #200ns;

    master_seq = axi_master_seq::type_id::create("master_seq");
    master_seq.start(env.agt.sqr);

    // Allow pipeline to drain
    #500ns;

    phase.drop_objection(this, "AXI test complete");
  endtask

  function void report_phase(uvm_phase phase);
    uvm_report_server svr;
    super.report_phase(phase);
    svr = uvm_report_server::get_server();
    if (svr.get_severity_count(UVM_FATAL) + svr.get_severity_count(UVM_ERROR) > 0)
      `uvm_info("TEST", "*** TEST FAILED ***", UVM_NONE)
    else
      `uvm_info("TEST", "*** TEST PASSED ***", UVM_NONE)
  endfunction

endclass

// ════════════════════════════════════════════════════════════
// UVM Top (tb_top)
// ════════════════════════════════════════════════════════════

// tb_top.sv
// Top-level testbench module


module tb_top;

 
  // ── Clock generation ──
  logic clk;
  initial begin
    clk = 0;
    forever #5ns clk = ~clk;  // 100MHz clock
  end

  // ── Interface instantiation ──
  axi_if #(
    .ADDR_WIDTH(32),
    .DATA_WIDTH(32),
    .ID_WIDTH(4)
  ) axi_vif (.ACLK(clk));

  // ── DUT instantiation ──
  axi_mem #(
    .ADDR_WIDTH(32),
    .DATA_WIDTH(32),
    .ID_WIDTH(4),
    .MEM_DEPTH(256)
  ) dut (
    .ACLK     (clk),
    .ARESETn  (axi_vif.ARESETn),
    // AW channel
    .AWID     (axi_vif.AWID),
    .AWADDR   (axi_vif.AWADDR),
    .AWLEN    (axi_vif.AWLEN),
    .AWSIZE   (axi_vif.AWSIZE),
    .AWBURST  (axi_vif.AWBURST),
    .AWVALID  (axi_vif.AWVALID),
    .AWREADY  (axi_vif.AWREADY),
    // W channel
    .WDATA    (axi_vif.WDATA),
    .WSTRB    (axi_vif.WSTRB),
    .WLAST    (axi_vif.WLAST),
    .WVALID   (axi_vif.WVALID),
    .WREADY   (axi_vif.WREADY),
    // B channel
    .BID      (axi_vif.BID),
    .BRESP    (axi_vif.BRESP),
    .BVALID   (axi_vif.BVALID),
    .BREADY   (axi_vif.BREADY),
    // AR channel
    .ARID     (axi_vif.ARID),
    .ARADDR   (axi_vif.ARADDR),
    .ARLEN    (axi_vif.ARLEN),
    .ARSIZE   (axi_vif.ARSIZE),
    .ARBURST  (axi_vif.ARBURST),
    .ARVALID  (axi_vif.ARVALID),
    .ARREADY  (axi_vif.ARREADY),
    // R channel
    .RID      (axi_vif.RID),
    .RDATA    (axi_vif.RDATA),
    .RRESP    (axi_vif.RRESP),
    .RLAST    (axi_vif.RLAST),
    .RVALID   (axi_vif.RVALID),
    .RREADY   (axi_vif.RREADY)
  );

  // ── Reset generation ──
  initial begin
    axi_vif.ARESETn = 0;
    // Initialize all master-side signals during reset
    axi_vif.AWVALID = 0;
    axi_vif.AWID    = 0;
    axi_vif.AWADDR  = 0;
    axi_vif.AWLEN   = 0;
    axi_vif.AWSIZE  = 0;
    axi_vif.AWBURST = 0;
    axi_vif.WVALID  = 0;
    axi_vif.WDATA   = 0;
    axi_vif.WSTRB   = 0;
    axi_vif.WLAST   = 0;
    axi_vif.BREADY  = 0;
    axi_vif.ARVALID = 0;
    axi_vif.ARID    = 0;
    axi_vif.ARADDR  = 0;
    axi_vif.ARLEN   = 0;
    axi_vif.ARSIZE  = 0;
    axi_vif.ARBURST = 0;
    axi_vif.RREADY  = 0;
    // Hold reset for multiple clock cycles
    repeat (10) @(posedge clk);
    axi_vif.ARESETn = 1;
    `uvm_info("TB_TOP", "Reset de-asserted", UVM_LOW)
  end

  // ── Virtual interface configuration ──
  initial begin
    uvm_config_db#(virtual axi_if)::set(null, "uvm_test_top.env.agt.drv", "vif", axi_vif);
    uvm_config_db#(virtual axi_if)::set(null, "uvm_test_top.env.agt.mon", "vif", axi_vif);
  end

  // ── Run test ──
  initial begin
    run_test("axi_base_test");
  end

  // ── Simulation timeout ──
  initial begin
    #100us;
    `uvm_fatal("TB_TOP", "Simulation timeout!")
  end

  // ── Waveform dump (optional) ──
  initial begin
    $dumpfile("axi_tb.vcd");
    $dumpvars(0, tb_top);
  end

endmodule

